      WHERE {
        ?stationLow sosa:resultTime "2010"^^xsd:gYear ;
                     sosa:observedProperty envthes:annual_median_dissolved_organic_carbon .
        ?stationLow hyobs:qMedian ?lowValue .
        ?stationLow geo:hasGeometry ?stationLowGeom .
        FILTER NOT EXISTS {
          ?otherStation sosa:resultTime "2010"^^xsd:gYear ;
                        sosa:observedProperty envthes:annual_median_dissolved_organic_carbon ;
                        hyobs:qMedian ?otherValue .
          FILTER(?otherValue < ?lowValue)
        }
      }
      LIMIT 1
    }
    ?stationHighGeom geo:asWKT ?wktHigh .
    ?stationLowGeom geo:asWKT ?wktLow .

    BIND(geof:distance(?wktHigh, ?wktLow) AS ?distance)
